import java.util.*;class Solution{public int ladderLength(String b,String e,List<String>wl){Set<String>d=new HashSet<>(wl);if(!d.contains(e))return 0;Queue<String>q=new ArrayDeque<>();Queue<Integer>s=new ArrayDeque<>();q.add(b);s.add(1);d.remove(b);while(!q.isEmpty()){String w=q.remove();int st=s.remove();if(w.equals(e))return st;char[]a=w.toCharArray();for(int i=0;i<a.length;i++){char old=a[i];for(char c='a';c<='z';c++){a[i]=c;String x=new String(a);if(d.remove(x)){q.add(x);s.add(st+1);}}a[i]=old;}}return 0;}}
